def transform(grid):
    h, w = len(grid), len(grid[0])
    points = [(r, c, grid[r][c])
              for r in range(h) for c in range(w) if grid[r][c]]

    # Identify the direction of the parallel diagonal stripes.
    d1 = {}
    d2 = {}
    for r, c, color in points:
        d1.setdefault(c - r, set()).add(color)
        d2.setdefault(c + r, set()).add(color)

    # Use the diagonal coordinate that groups the marks into colored stripes.
    groups = d1 if len(d1) <= len(d2) else d2
    use_difference = groups is d1
    samples = [(k, next(iter(v))) for k, v in groups.items() if len(v) == 1]

    if not samples:
        return [row[:] for row in grid]

    # Find the shortest repeating stripe period consistent with the marks.
    period = 1
    for p in range(1, max(h, w) + 1):
        residue_colors = {}
        valid = True
        for k, color in samples:
            residue = k % p
            if residue in residue_colors and residue_colors[residue] != color:
                valid = False
                break
            residue_colors[residue] = color
        if valid:
            period = p
            break

    known = {}
    for k, color in samples:
        known[k % period] = color

    # Extend each marked color through any unmarked residues until the next
    # observed stripe.
    seq = [None] * period
    for i in range(period):
        if i in known:
            seq[i] = known[i]
        else:
            j = (i - 1) % period
            while seq[j] is None:
                j = (j - 1) % period
            seq[i] = seq[j]

    return [[seq[((c - r) if use_difference else (c + r)) % period]
             for c in range(w)] for r in range(h)]
